function nextPage(rows, cursor, pageSize){
  // rows pre-sorted by created_at DESC, id DESC. cursor = {created_at,id} or null for first page.
  let pool = rows;
  if (cursor){
    pool = rows.filter(r => r.created_at < cursor.created_at);
  }
  const page = pool.slice(0, pageSize);
  return page;
}
this.nextPage = nextPage;

